        const targetVal = origin[key as string]
        if (
          (!isSymbol(key) && !Object.getOwnPropertyNames(newComer).includes(key)) ||
          (isSymbol(key) && !Object.getOwnPropertySymbols(newComer).includes(key))
        ) {
          assignProp(
            carry as Record<string | number | symbol, unknown>,
            key as string,
            targetVal,
            origin,
          )
        }
        return carry
      },
      {} as (T1 & T2) | T2,
    )
  }
  // newObject has all properties that newComer hasn't
  const props = Object.getOwnPropertyNames(newComer)
  const symbols = Object.getOwnPropertySymbols(newComer)
  const result = [...props, ...symbols].reduce((carry, key) => {
    // Skip __proto__ properties to prevent prototype poisoning
    if (key === '__proto__') return carry
    // re-define the origin and newComer as targetVal and newVal
    let newVal = newComer[key as string]
    const targetVal = isPlainObject(origin) ? origin[key as string] : undefined
    // When newVal is an object do the merge recursively
    if (targetVal !== undefined && isPlainObject(newVal)) {
      newVal = mergeRecursively(targetVal as any, newVal as any, compareFn)
    }
    const propToAssign = compareFn ? compareFn(targetVal as any, newVal as any, key as any) : newVal
    assignProp(
      carry as Record<string | number | symbol, unknown>,
      key as string,
      propToAssign,
      newComer,
    )
    return carry
  }, newObject)
  return result
}

/**
 * Merge anything recursively. Objects get merged, special objects (classes etc.) are re-assigned
 * "as is". Basic types overwrite objects or other basic types.
 */
export function merge<T, const Tn extends unknown[]>(object: T, ...otherObjects: Tn): Merge<T, Tn> {
  return otherObjects.reduce((result, newComer) => {
    return mergeRecursively(result, newComer)
  }, object) as any
}

export function mergeAndCompare<T, const Tn extends unknown[]>(
  compareFn: (prop1: unknown, prop2: unknown, propName: string | symbol) => any,
  object: T,
  ...otherObjects: Tn
): Merge<T, Tn> {
  return otherObjects.reduce((result, newComer) => {
    return mergeRecursively(result, newComer, compareFn)
  }, object) as any
}

export function mergeAndConcat<T, const Tn extends unknown[]>(
  object: T,
  ...otherObjects: Tn
): Merge<T, Tn> {
  return otherObjects.reduce((result, newComer) => {
    return mergeRecursively(result, newComer, concatArrays)
  }, object) as any
}

