test('works with very deep props & dates', () => {
  const newDate = new Date()
  const origin = {
    info: {
      time: 'now',
      newDate,
      very: { deep: { prop: false } },
    },
  }
  const target = {
    info: {
      date: 'tomorrow',
      very: { deep: { prop: true } },
    },
  }
  const res = merge(origin, target)
  expect(res).toEqual({
    info: {
      time: 'now',
      newDate,
      date: 'tomorrow',
      very: { deep: { prop: true } },
    },
  })
  expect(origin).toEqual({
    info: {
      time: 'now',
